package com.shubhasai.monkeymart

import com.shubhasai.monkeymart.analytics.ScreenTracker
import com.shubhasai.monkeymart.data.Product
import com.shubhasai.monkeymart.ui.DealLoader
import java.lang.ref.WeakReference
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Test

class DealLoaderTest {

    private val product = Product(1, "Banana Bunch", "x", 6_000, "desc", 10)

    @Test
    fun cancelledScopeNeverShowsDeal() = runBlocking {
        val job = Job()
        val scope = CoroutineScope(job + Dispatchers.Unconfined)
        var shown = 0

        DealLoader.load(scope, loader = { delay(300); product }, showDeal = { shown++ })
        scope.coroutineContext[Job]!!.cancel()
        delay(600)

        assertEquals(0, shown)
        assertFalse(job.children.any { it.isActive })
    }

    @Test
    fun liveScopeShowsDeal() = runBlocking {
        val scope = CoroutineScope(Job() + Dispatchers.Unconfined)
        var shown = 0

        DealLoader.load(scope, loader = { delay(50); product }, showDeal = { shown++ })
        delay(300)

        assertEquals(1, shown)
    }

    @Test
    fun screenTrackerDoesNotHoldScreens() {
        var screen: Any? = Any()
        val ref = WeakReference(screen)
        ScreenTracker.onScreenCreated(screen!!)
        screen = null

        repeat(5) {
            System.gc()
            Thread.sleep(20)
        }

        assertNull(ref.get())
    }
}

